from common import *

politics = [
 card("pol-001", "politics",
  ("La Ve République", "The Fifth Republic"),
  ("La Constitution du 4 octobre 1958 renforce l'exécutif après l'instabilité de la IVe République. Le président de la République nomme le Premier ministre, qui dirige le gouvernement et répond devant l'Assemblée nationale. Depuis le référendum de 1962, le président est élu au suffrage universel direct. Les constitutionnalistes débattent de la qualification du régime : semi-présidentiel pour les uns, parlementaire « rationalisé » pour les autres.",
   "The Constitution of 4 October 1958 strengthened the executive after the instability of the Fourth Republic. The President appoints the Prime Minister, who leads the government and is accountable to the National Assembly. Since the 1962 referendum the President has been elected by direct universal suffrage. Constitutional scholars debate how to classify the regime: semi-presidential for some, a “rationalised” parliamentary system for others."),
  ("Depuis 1962, le président est élu au suffrage universel direct.", "Since 1962 the President has been directly elected."),
  quiz(("Depuis quel référendum le président est-il élu au suffrage universel direct ?", "Since which referendum has the President been directly elected?"),
       [("1958", "1958"), ("1962", "1962"), ("1969", "1969"), ("2000", "2000")],
       1, ("Le référendum de 2000 a réduit le mandat de sept à cinq ans.", "The 2000 referendum cut the term from seven to five years.")),
  [S("Constitution du 4 octobre 1958", "Conseil constitutionnel", "https://www.conseil-constitutionnel.fr"), S("Les institutions de la Ve République", "Vie publique", "https://www.vie-publique.fr")],
  tags=["france", "institutions"]),

 card("pol-002", "politics",
  ("Le Conseil constitutionnel", "The Constitutional Council"),
  ("Le Conseil constitutionnel compte neuf membres nommés pour neuf ans, renouvelés par tiers tous les trois ans : trois par le président de la République, trois par le président de l'Assemblée nationale, trois par le président du Sénat. Les anciens présidents de la République en sont membres de droit. Depuis 2010, tout justiciable peut, par la question prioritaire de constitutionnalité (QPC), contester une loi déjà en vigueur.",
   "The Constitutional Council has nine members appointed for nine years, a third renewed every three years: three by the President of the Republic, three by the President of the National Assembly and three by the President of the Senate. Former Presidents of the Republic are members by right. Since 2010 any litigant can challenge a law already in force through the priority question of constitutionality (QPC)."),
  ("La QPC permet, depuis 2010, de contester une loi en vigueur.", "Since 2010 the QPC lets citizens challenge a law already in force."),
  quiz(("Combien de membres nommés compte le Conseil constitutionnel ?", "How many appointed members sit on the Constitutional Council?"),
       [("7", "7"), ("9", "9"), ("12", "12"), ("15", "15")],
       1, ("S'y ajoutent les anciens présidents qui choisissent de siéger.", "Former Presidents who choose to sit are added to them.")),
  [S("Composition", "Conseil constitutionnel", "https://www.conseil-constitutionnel.fr"), S("Constitution, art. 56 et 61-1", "Légifrance", "https://www.legifrance.gouv.fr")],
  tags=["france", "droit"]),

 card("pol-003", "politics",
  ("Qui fait quoi dans l'Union européenne ?", "Who does what in the European Union?"),
  ("La Commission européenne propose les textes et veille à l'application des traités. Le Parlement européen, élu au suffrage direct, et le Conseil de l'UE, qui réunit les ministres des États, adoptent ensemble la plupart des lois. Le Conseil européen, formé des chefs d'État ou de gouvernement, fixe les grandes orientations. La Cour de justice garantit l'interprétation uniforme du droit.",
   "The European Commission proposes legislation and ensures the treaties are applied. The European Parliament, directly elected, and the Council of the EU, which brings together national ministers, jointly adopt most laws. The European Council, made up of heads of state or government, sets the overall direction. The Court of Justice ensures EU law is interpreted uniformly."),
  ("Ne confondez pas Conseil européen, Conseil de l'UE et Conseil de l'Europe.", "Don't confuse the European Council, the Council of the EU and the Council of Europe."),
  quiz(("Quelle institution détient, en règle générale, l'initiative législative ?", "Which institution generally holds the right of legislative initiative?"),
       [("Le Parlement européen", "The European Parliament"), ("Le Conseil européen", "The European Council"), ("La Commission européenne", "The European Commission"), ("La Cour de justice", "The Court of Justice")],
       2, ("Le Conseil de l'Europe, à Strasbourg, est une organisation distincte de l'UE.", "The Council of Europe in Strasbourg is a separate organisation from the EU.")),
  [S("Institutions et organes de l'UE", "Union européenne", "https://european-union.europa.eu"), S("Comprendre l'Union européenne", "Toute l'Europe", "https://www.touteleurope.eu")],
  tags=["europe", "institutions"]),

 card("pol-004", "politics",
  ("Le fédéralisme allemand", "German federalism"),
  ("La République fédérale d'Allemagne réunit seize Länder, dotés de leurs propres parlements et gouvernements, notamment compétents pour l'éducation et la police. Au niveau fédéral, le Bundestag élit le chancelier ; le Bundesrat représente les gouvernements des Länder. Le chancelier ne peut être renversé que par une « motion de censure constructive », qui oblige à élire simultanément un successeur.",
   "The Federal Republic of Germany brings together sixteen Länder, each with its own parliament and government, responsible in particular for education and policing. At federal level the Bundestag elects the Chancellor; the Bundesrat represents the Länder governments. The Chancellor can only be removed by a “constructive vote of no confidence”, which requires electing a successor at the same time."),
  ("La censure « constructive » impose d'élire un successeur pour renverser le chancelier.", "The “constructive” no-confidence vote requires electing a successor to remove the Chancellor."),
  quiz(("Combien de Länder compte l'Allemagne ?", "How many Länder does Germany have?"),
       [("11", "11"), ("13", "13"), ("16", "16"), ("21", "21")],
       2, ("Avant 1990, la RFA en comptait onze (Berlin-Ouest inclus, avec un statut particulier).", "Before 1990 West Germany had eleven (including West Berlin, with a special status).")),
  [S("Grundgesetz, Art. 67", "Deutscher Bundestag", "https://www.bundestag.de"), S("Föderalismus", "Bundeszentrale für politische Bildung", "https://www.bpb.de")],
  tags=["allemagne", "institutions"]),

 card("pol-005", "politics",
  ("Montesquieu et la séparation des pouvoirs", "Montesquieu and the separation of powers"),
  ("Dans De l'esprit des lois (1748), Montesquieu soutient que, pour éviter l'abus, « le pouvoir arrête le pouvoir » : les fonctions législative, exécutive et judiciaire doivent être confiées à des organes distincts. Inspiré par sa lecture des institutions anglaises, ce principe influence la Constitution américaine de 1787 et l'article 16 de la Déclaration de 1789.",
   "In The Spirit of the Laws (1748) Montesquieu argued that to prevent abuse “power must check power”: legislative, executive and judicial functions should be entrusted to separate bodies. Inspired by his reading of English institutions, the principle influenced the 1787 US Constitution and Article 16 of the 1789 Declaration."),
  ("« Il faut que, par la disposition des choses, le pouvoir arrête le pouvoir. »", "“Power must, by the arrangement of things, check power.”"),
  quiz(("Dans quel ouvrage Montesquieu expose-t-il ce principe ?", "In which work does Montesquieu set out this principle?"),
       [("Du contrat social", "The Social Contract"), ("De l'esprit des lois", "The Spirit of the Laws"), ("Lettres philosophiques", "Philosophical Letters"), ("Lettres persanes", "Persian Letters")],
       1, ("Du contrat social est de Rousseau (1762) ; les Lettres persanes, de Montesquieu aussi, sont un roman épistolaire.", "The Social Contract is by Rousseau (1762); the Persian Letters, also by Montesquieu, is an epistolary novel.")),
  [S("De l'esprit des lois", "Gallica — BnF", "https://gallica.bnf.fr"), S("Déclaration de 1789, art. 16", "Légifrance", "https://www.legifrance.gouv.fr")],
  tags=["philosophie politique", "lumières"]),

 card("pol-006", "politics",
  ("La laïcité et la loi de 1905", "Laïcité and the 1905 law"),
  ("La loi du 9 décembre 1905 garantit le libre exercice des cultes et dispose que la République n'en reconnaît ni n'en subventionne aucun. Son interprétation fait débat : certains défendent une laïcité de stricte neutralité de l'État, qui protège la liberté de conscience sans restreindre l'expression religieuse des citoyens ; d'autres plaident pour une conception plus exigeante, qui étend la discrétion religieuse à certains espaces publics pour préserver un socle commun.",
   "The law of 9 December 1905 guarantees the free exercise of religion and states that the Republic neither recognises nor subsidises any faith. Its interpretation is debated: some defend a laïcité of strict state neutrality, which protects freedom of conscience without restricting citizens' religious expression; others argue for a more demanding conception that extends religious restraint to certain public spaces to preserve common ground."),
  ("La loi de 1905 sépare les Églises et l'État ; son interprétation reste débattue.", "The 1905 law separates Churches and State; how to interpret it is still debated."),
  quiz(("En quelle année est votée la loi de séparation des Églises et de l'État ?", "In which year was the law separating Churches and State passed?"),
       [("1882", "1882"), ("1905", "1905"), ("1946", "1946"), ("1958", "1958")],
       1, ("1882 renvoie aux lois Ferry sur l'école laïque et obligatoire.", "1882 refers to the Ferry laws on secular, compulsory schooling.")),
  [S("Loi du 9 décembre 1905", "Légifrance", "https://www.legifrance.gouv.fr"), S("Laïcité", "Vie publique", "https://www.vie-publique.fr")],
  tags=["france", "débat"]),

 card("pol-007", "politics",
  ("Le collège électoral américain", "The US Electoral College"),
  ("Le président des États-Unis n'est pas élu directement par les citoyens mais par 538 grands électeurs, répartis entre les États selon leur représentation au Congrès (plus trois pour Washington D.C.). Dans presque tous les États, le candidat arrivé en tête remporte tous les électeurs. Ses défenseurs y voient une protection des petits États et du fédéralisme ; ses critiques soulignent qu'un candidat peut l'emporter sans majorité du vote populaire, comme en 2000 et 2016.",
   "The US President is not elected directly by citizens but by 538 electors, allocated among the states according to their representation in Congress (plus three for Washington, D.C.). In almost every state the candidate who comes first wins all its electors. Supporters see it as protecting small states and federalism; critics point out that a candidate can win without a majority of the popular vote, as in 2000 and 2016."),
  ("Il faut 270 grands électeurs sur 538 pour être élu.", "A candidate needs 270 of the 538 electoral votes to win."),
  quiz(("Combien de grands électeurs faut-il pour remporter la présidence ?", "How many electoral votes are needed to win the presidency?"),
       [("218", "218"), ("270", "270"), ("290", "290"), ("538", "538")],
       1, ("Le Maine et le Nebraska répartissent une partie de leurs électeurs par circonscription.", "Maine and Nebraska allocate some of their electors by district.")),
  [S("Electoral College", "U.S. National Archives", "https://www.archives.gov/electoral-college")],
  tags=["états-unis", "élections", "débat"]),

 card("pol-008", "politics",
  ("Scrutin majoritaire ou proportionnel ?", "Majoritarian or proportional voting?"),
  ("Les députés français sont élus au scrutin majoritaire uninominal à deux tours, dans des circonscriptions. L'Allemagne pratique une proportionnelle personnalisée : chaque électeur dispose d'une voix pour un candidat local et d'une voix pour une liste, avec un seuil de 5 % des secondes voix (assorti d'exceptions). Les partisans du majoritaire mettent en avant la stabilité et le lien avec le territoire ; ceux de la proportionnelle, une représentation plus fidèle de la diversité des opinions.",
   "French deputies are elected by two-round, single-member majority voting in constituencies. Germany uses personalised proportional representation: each voter has one vote for a local candidate and one for a party list, with a 5% threshold on second votes (with exceptions). Supporters of majoritarian voting stress stability and the link with a constituency; supporters of proportional voting, a more faithful representation of the range of opinions."),
  ("Chaque mode de scrutin arbitre entre stabilité et représentativité.", "Every voting system trades off stability against representativeness."),
  quiz(("Quel est le seuil appliqué aux secondes voix en Allemagne ?", "What threshold applies to second votes in Germany?"),
       [("3 %", "3%"), ("5 %", "5%"), ("10 %", "10%"), ("Aucun", "None")],
       1, ("Les exceptions à ce seuil ont été modifiées par la réforme électorale de 2023, puis par une décision de la Cour constitutionnelle fédérale en 2024.", "The exceptions to this threshold were changed by the 2023 electoral reform and then by a Federal Constitutional Court ruling in 2024.")),
  [S("Élections législatives", "Vie publique", "https://www.vie-publique.fr"), S("Wahlsystem", "Der Bundeswahlleiter", "https://www.bundeswahlleiterin.de")],
  tags=["élections", "comparaison", "débat"]),
]

